// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(uint256 amount, address receiver) public {
        vm.assume(receiver != address(0));
        amount = bound(amount, 2, 1 ether);
        vm.deal(address(c), amount);
        vm.prank(address(this));
        c.sendTo(receiver, amount);
        assertTrue(receiver.balance == amount, "receiver must be credited exactly amount");
    }
}
